#[cfg(test)]
mod tests {
    use std::{collections::HashSet, fs, path::Path};

    use super::*;

    #[test]
    fn painting_variant_catalog_is_complete_contiguous_and_unique() {
        assert_eq!(VANILLA_PAINTING_VARIANTS.len(), 51);
        let mut resources = HashSet::new();
        for (id, entry) in VANILLA_PAINTING_VARIANTS.iter().enumerate() {
            assert_eq!(entry.id, id as i32);
            assert!(entry.width > 0);
            assert!(entry.height > 0);
            assert!(resources.insert(entry.resource_id));
        }
    }

    #[test]
    fn painting_variant_catalog_preserves_vanilla_order_and_properties() {
        assert_eq!(
            vanilla_painting_variant_resource_id(0),
            Some("minecraft:kebab")
        );
        assert_eq!(
            vanilla_painting_variant_resource_id(50),
            Some("minecraft:dennis")
        );
        assert_eq!(vanilla_painting_variant_resource_id(-1), None);
        assert_eq!(vanilla_painting_variant_resource_id(51), None);
        assert!(!vanilla_painting_variant(19).unwrap().has_author);
        let dennis = vanilla_painting_variant(50).unwrap();
        assert_eq!((dennis.width, dennis.height), (3, 3));
    }

    #[test]
    fn production_sources_do_not_redeclare_painting_variant_catalog_facts() {
        fn visit(directory: &Path, violations: &mut Vec<String>) {
            for entry in fs::read_dir(directory).unwrap() {
                let path = entry.unwrap().path();
                if path.is_dir() {
                    visit(&path, violations);
                    continue;
                }
                if path.extension().and_then(|value| value.to_str()) != Some("rs") {
                    continue;
                }
                let display = path.to_string_lossy();
                if display.ends_with("/painting_variants.rs")
                    || display.ends_with("/tests.rs")
                    || display.contains("/tests/")
                {
                    continue;
                }
                let source = fs::read_to_string(&path).unwrap();
                let production = source.split("#[cfg(test)]").next().unwrap_or(&source);
                if production.contains("PAINTING_VARIANT_SIZES")
                    || production.contains("struct VanillaPaintingVariant")
                    || production.contains("const VANILLA_PAINTING_VARIANTS")
                {
                    violations.push(display.to_string());
                }
            }
        }
        let mut violations = Vec::new();
        visit(
            Path::new(env!("CARGO_MANIFEST_DIR")).parent().unwrap(),
            &mut violations,
        );
        assert!(
            violations.is_empty(),
            "parallel painting-variant catalog owners: {violations:?}"
        );
    }
}
